  labels: out.map(o => `${o.i}: ${o.was} -> ${o.now || '(скрыто)'}`),
};
writeFileSync(D8 + 'gate_tk009.json', JSON.stringify({ res, out }, null, 1));
console.log(JSON.stringify({ ...res, labels: undefined }, null, 1));
console.log(res.labels.join('\n'));

