import { createReadStream, existsSync, readFileSync } from 'node:fs';
import { createInterface } from 'node:readline';
import { GoogleCacheCollection, OpenCitiesCollection, VenuesCollection, type OpenCity, type Venue } from '/imports/api/collections';
import { RATING_TTL_DAYS } from '/imports/api/places/googleRatings';
import { coreWords, nameKey } from '/imports/domain/nameKey';
import { venueTypeOf } from '/imports/domain/venueTypes';

/**
 * Loads the open venue base from an NDJSON export (one venue per line) and a
 * cities JSON next to it. Set VENUES_FILE to the .ndjson path; the cities file
 * is VENUES_CITIES_FILE or `cities.json` in the same folder.
 *
 * Venues are upserted by venueId, so a monthly re-export (VENUES_REIMPORT=1)
 * only adds new venues and refreshes existing ones.
 */
export async function importVenuesIfConfigured() {
  // Google content expires by itself: Google allows it only as a 30-day cache.
  const cache = GoogleCacheCollection.rawCollection();
  await cache.createIndex({ venueId: 1 }, { unique: true });
  await cache.createIndex({ fetchedAt: 1 }, { expireAfterSeconds: RATING_TTL_DAYS * 86_400 });

  const file = process.env.VENUES_FILE;
  if (!file) return;
  if (!existsSync(file)) {
    console.warn(`[venues] VENUES_FILE not found: ${file}`);
    return;
  }

  const raw = VenuesCollection.rawCollection();
  await raw.createIndex({ venueId: 1 }, { unique: true });
  await raw.createIndex({ city: 1, nameKey: 1 });
  await raw.createIndex({ city: 1, altKeys: 1 });
  await raw.createIndex({ city: 1, compactKey: 1 });
  await raw.createIndex({ city: 1, chainKey: 1 });
  await raw.createIndex({ city: 1, candidate: 1, primaryType: 1, confidence: -1 });
  await raw.createIndex({ city: 1, candidate: 1, attested: 1, vtype: 1, confidence: -1 });
  await OpenCitiesCollection.rawCollection().createIndex({ placeId: 1 }, { unique: true });

  const citiesFile = process.env.VENUES_CITIES_FILE ?? file.replace(/[^\\/]+$/, 'cities.json');
  if (existsSync(citiesFile)) {
    const cities = JSON.parse(readFileSync(citiesFile, 'utf8')) as OpenCity[];
    for (const city of cities) {
      await OpenCitiesCollection.upsertAsync({ placeId: city.placeId }, { $set: city });
    }
  }

  // A loaded base is reused across restarts; VENUES_REIMPORT=1 forces a refresh.
  if (process.env.VENUES_REIMPORT !== '1' && await raw.estimatedDocumentCount() > 0) return;

  const started = Date.now();
  let batch: any[] = [];
  let count = 0;
  const flush = async () => {
    if (!batch.length) return;
    await raw.bulkWrite(batch, { ordered: false });
    count += batch.length;
    batch = [];
  };
  const lines = createInterface({ input: createReadStream(file, 'utf8'), crlfDelay: Infinity });
  for await (const line of lines) {
    if (!line.trim()) continue;
    const venue = JSON.parse(line) as Omit<Venue, 'nameKey' | 'altKeys' | 'compactKey' | 'chainKey'>;
    const doc: Venue = {
      ...venue,
      altNames: venue.altNames ?? [],
      nameKey: nameKey(venue.name),
      compactKey: nameKey(venue.name).replace(/ /g, ''),
      attested: (venue.sources?.length ?? 1) > 1,
      vtype: venueTypeOf({ primaryType: venue.primaryType, types: venue.types }) ?? '',
      chainKey: coreWords(nameKey(venue.name)).slice(0, 2).join(' '),
      altKeys: (venue.altNames ?? []).map(nameKey).filter(Boolean),
    };
    // Keep a photo already looked up; everything else comes from the export.
    const { photoUrl: _keep, ...fields } = doc;
    batch.push({ updateOne: { filter: { venueId: doc.venueId }, update: { $set: fields }, upsert: true } });
    if (batch.length >= 2000) await flush();
  }
  await flush();

  // A name repeated across a city is a chain: a person's own find is never "All Bar One".
  const chains = await raw.aggregate([
    { $match: { candidate: true, chainKey: { $ne: '' } } },
