import type { Place } from '/imports/domain/types';

/**
 * Places provider. The Google key never reaches the client:
 * autocomplete, details and photos are all proxied by the server.
 * That also gives us the shared place cache (spec 9.2) and quota control.
 */
export interface PlaceSuggestion {
  placeId: string;
  name: string;
  city: string;
  area?: string;
  /** Present when the source knows them — the map needs them to drop a pin. */
  lat?: number;
  lng?: number;
  photoUrl?: string;
  photoAttribution?: string;
  /**
   * True once the place has been turned into a seed event. Such a place stays
   * on the screen — it is part of the profile now — but it can no longer be
   * taken back, because events are append-only.
   */
  committed?: boolean;
  /** Transient billing token; persisted only until the selected prediction is
   * resolved to details, then discarded with the draft. */
  sessionToken?: string;
}

export interface CitySuggestion {
  placeId: string;
  /** What we show and what goes into the prompt: "Bangkok, Thailand". */
  label: string;
  /** Just the city: "Bangkok". */
  city: string;
}

/** A short-lived image URL returned by the Places Photo API. */
export interface PlacePhoto {
  url: string;
  attribution?: string;
}

/**
 * A place plus the transient bits we are allowed to read but not to keep:
 * Places terms limit how long third-party content may be cached, so review
 * text is used at enrichment time and never written to our collection.
 */
export interface PlaceDetails extends Place {

