import { Mongo } from 'meteor/mongo';
import type { VergerEvent, Place, Profile, Trip } from '/imports/domain/types';

/**
 * Spec 9. Events are append-only; a place is a system-wide shared cache;
 * profile and trip are derived.
 */
export const EventsCollection = new Mongo.Collection<VergerEvent>('events');
export const PlacesCollection = new Mongo.Collection<Place>('places');
export const ProfilesCollection = new Mongo.Collection<Profile>('profiles');
export const TripsCollection = new Mongo.Collection<Trip>('trips');

export interface WishlistEntry {
  _id?: string;
  userId: string;
  placeId: string;
  place: Place;
  createdAt: Date;
}
export const WishlistCollection = new Mongo.Collection<WishlistEntry>('wishlist');

/** Private product feedback, readable only through the super-admin operation. */
export interface ProductFeedback {
  _id: string;
  userId: string;
  text: string;
  locale: 'ru' | 'en';
  page: string;
  createdAt: Date;
}
export const ProductFeedbackCollection = new Mongo.Collection<ProductFeedback>('productFeedback');

/**
 * Quality 10 — the first pass is impersonal, so its result belongs to the city
 * rather than to the person. Cached, the second traveller to the same city
 * pays only for ranking: no web search, and no liveness checks re-run.
 */
export interface CityCandidates {
  _id?: string;
  city: string;
  candidates: { n: string; a: string; s: string; dn: 'night' | 'day' }[];
  createdAt: Date;
}

export const CityCandidatesCollection = new Mongo.Collection<CityCandidates>('cityCandidates');

/**
 * The seed list while it is still being edited. Not an event: it is mutable
 * by nature, and it only becomes events when the person commits it. Kept
 * server-side so a reload never loses what was typed.
 */
export interface Draft {
  _id?: string;
  userId: string;
  places: {
    placeId: string;
    name: string;
    city: string;
    area?: string;
    photoUrl?: string;
    photoAttribution?: string;
    sessionToken?: string;
  }[];
  updatedAt: Date;
}

export const DraftsCollection = new Mongo.Collection<Draft>('drafts');

/** Private-beta applications, including campaign attribution. */
export type AccessRequestStatus = 'open' | 'processing' | 'awaiting_delivery' | 'processed' | 'delivery_failed';
export type InvitationDeliveryState = 'not_sent' | 'unconfirmed' | 'awaiting' | 'delivered' | 'failed';

export interface AccessRequestAttribution {
  source: string;
  medium?: string;
  campaign?: string;
  content?: string;
  term?: string;
  landingPath?: string;
}

export interface AccessRequest {
  _id?: string;
  firstName?: string;
  lastName?: string;
  email: string;
  /** `emailKey(email)`: one value for every spelling of the same mailbox, so
   * `j.doe+x@gmail.com` and `jdoe@gmail.com` count as one application. */
  emailKey?: string;
  attribution: AccessRequestAttribution;
  status: AccessRequestStatus;
  createdAt: Date;
  processedAt?: Date;
  processedBy?: string;
  accountId?: string;
  lastError?: string;
  deliveryMessageId?: string;
  deliveryTag?: string;
  deliveryAcceptedAt?: Date;
  deliveredAt?: Date;
  deliveryEvent?: string;
  /** Kept separate from workflow status so legacy data can be migrated without
   * rewriting account state, and Mongo can filter delivery work efficiently. */
  deliveryState?: InvitationDeliveryState;
}

export const AccessRequestsCollection = new Mongo.Collection<AccessRequest>('accessRequests');

/** Server-side operational failures. This is intentionally not published to
 * clients; super-admins access a redacted view through an operation. */
export interface ErrorLog {
  _id?: string;
  createdAt: Date;
  operation: string;
  message: string;
  name?: string;
  code?: string;
  details?: string;
  stack?: string;
  actorUserId?: string;
  affectedUserId?: string;
  subjectEmail?: string;
  context?: Record<string, string>;
}

export const ErrorLogsCollection = new Mongo.Collection<ErrorLog>('errorLogs');

/** Atomic, server-owned budget counters. A user never supplies these values. */
export interface UsageQuota {
  _id?: string;
  userId: string;
  period: string;
  trips: number;
  tokensReserved: number;
  tokensUsed: number;
  /** Failed runs given back in this period; capped by TRIP_REFUNDS_PER_USER. */
  refunds?: number;
  updatedAt: Date;
}

export const UsageQuotasCollection = new Mongo.Collection<UsageQuota>('usageQuotas');

/** Shared, TTL-backed request windows. Unlike an in-process Map, these limits
 * survive restarts and are shared by every application replica. */
export interface RequestRateLimit {
  _id?: string;
  scope: string;
  key: string;
  windowStartedAt: Date;
  count: number;
  expiresAt: Date;
}

export const RequestRateLimitsCollection = new Mongo.Collection<RequestRateLimit>('requestRateLimits');

/** Global, server-owned provider request counters. They bound the maximum
 * blast radius even when many legitimate accounts are compromised. */
export interface ProviderBudget {
  _id?: string;
  provider: string;
  period: string;
  requests: number;
  updatedAt: Date;
}
export const ProviderBudgetsCollection = new Mongo.Collection<ProviderBudget>('providerBudgets');

/** A venue from our own open-data base (Overture Maps), loaded monthly.
 * `nameKey`/`altKeys` are normalized spellings for lookups without an API. */
export interface Venue {
  _id?: string;
  venueId: string;
  name: string;
  altNames: string[];
  nameKey: string;
  altKeys: string[];
  /** nameKey without spaces: "BarroNegro" and "Barro Negro" meet here. */
  compactKey: string;
  /** First distinctive words of the name; shared by the branches of a chain. */
  chainKey: string;
  /** Three or more venues in the city share the chainKey: All Bar One, Slug & Lettuce. */
  chain?: boolean;
  city: string;
  country: string;
  countryCode: string;
  lat: number;
  lng: number;
  types: string[];
  primaryType: string;
  confidence: number;
  /** Reliable, open and of a type Verger recommends. Others exist only so
   * people can find their own favourite places. */
  candidate: boolean;
  website?: string;
  /** Image the venue publishes for link previews; '' once looked up and absent. */
  photoUrl?: string;
  /** Google place_id for the photo fallback ('' when Google has no match). Storing
   * place_id is allowed by Google's terms; the photo itself is fetched each time. */
  googlePlaceId?: string;
  source: 'overture' | 'foursquare';
  /** Every open dataset the venue was found in; two sources mean a well-attested venue. */
  sources?: ('overture' | 'foursquare')[];
  /** Known to both open maps: the strongest signal of a real, noticed venue. Indexed. */
  attested?: boolean;
  /** Verger venue type (bar, club, wine, cocktail, restaurant...) computed at import, indexed. */
  vtype?: string;
  fsqId?: string;
  /** Foursquare's closing date; such venues stay findable but are never picked. */
  closedAt?: string;
  /** Release the venue first appeared in — the "is it new" signal. */
  firstSeen?: string;
}
export const VenuesCollection = new Mongo.Collection<Venue>('venues');

/** Cities covered by the venue base; their ids double as cityPlaceId. */
export interface OpenCity {
  _id?: string;
  placeId: string;
  city: string;
  label: string;
  country: string;
  countryCode: string;
  lat: number;
  lng: number;
  /** When each Google ratings query for this city last ran, by query text. */
  ratingsRefreshedAt?: Record<string, Date>;
}
export const OpenCitiesCollection = new Mongo.Collection<OpenCity>('openCities');

/**
 * Google content kept apart from our own venue base: Google allows it only as
 * a temporary cache, so a TTL index deletes each entry 30 days after it was
 * fetched. Only `Venue.googlePlaceId` (a reference) lives on the venue itself.
 */
export interface GoogleCacheEntry {
  _id?: string;
  venueId: string;
  rating?: number;
  ratingCount?: number;
  fetchedAt: Date;
}
export const GoogleCacheCollection = new Mongo.Collection<GoogleCacheEntry>('googleCache');

