const source = readFileSync(new URL('../app/imports/api/places/areaFromCoords.ts', import.meta.url), 'utf8');
const code = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 } }).outputText;
runInNewContext(code, { exports, console, fetch: () => assert.fail('network'), AbortSignal, Number, Map, Promise, setTimeout, Date });
const { pickArea, areaForPoint, areaFromCoordsEnabled, resetAreaCache } = exports;

test('flag: only AREA_SOURCE=coords turns it on', () => {
  assert.equal(areaFromCoordsEnabled({}), false);
