// TK-010: записать подписи районов (tk010/areas.ndjson) в поле `area` мест локальной Mongo. Без VENUES_REIMPORT.
// Запуск: node tools/tk010_apply.mjs [areas.ndjson] [--unset]   (--unset снимает поле у всех мест — откат)
// Mongo: MONGO_URL или mongodb://127.0.0.1:3201 ; база meteor (run-local.ps1).
import { createReadStream } from 'node:fs';
import { createInterface } from 'node:readline';
import { createRequire } from 'node:module';

const { MongoClient } = createRequire(import.meta.url)('../app/node_modules/mongodb');
const args = process.argv.slice(2);
const unset = args.includes('--unset');
const file = args.find(a => !a.startsWith('--')) ?? 'C:/verger-data/pilot/tk010/areas.ndjson';
const client = await MongoClient.connect(process.env.MONGO_URL ?? 'mongodb://127.0.0.1:3201');
const venues = client.db(process.env.MONGO_DB ?? 'meteor').collection('venues');

if (unset) {
  const r = await venues.updateMany({ area: { $exists: true } }, { $unset: { area: '' } });
  console.log(`unset area on ${r.modifiedCount} venues`);
} else {
  let batch = [], n = 0;
  const flush = async () => { if (batch.length) { await venues.bulkWrite(batch, { ordered: false }); n += batch.length; batch = []; } };
  for await (const line of createInterface({ input: createReadStream(file, 'utf8'), crlfDelay: Infinity })) {
    if (!line.trim()) continue;
    const { venueId, area } = JSON.parse(line);
    batch.push({ updateOne: { filter: { venueId }, update: { $set: { area } } } });
    if (batch.length >= 5000) await flush();
  }
  await flush();
  console.log(`set area on ${n} venues, with area now: ${await venues.countDocuments({ area: { $exists: true } })} of ${await venues.estimatedDocumentCount()}`);
}
await client.close();

